#pragma once
/*
 * Font metrics tables generated by tools/gen_tables.py (gen_tables.c).
 */
#include <pebble.h>

// Firmware fonts used for text, in the order of the preview's TEXT_FONTS
typedef enum {
  SYSFONT_GOTHIC_14,
  SYSFONT_GOTHIC_14_BOLD,
  SYSFONT_GOTHIC_18,
  SYSFONT_GOTHIC_18_BOLD,
  SYSFONT_GOTHIC_24,
  SYSFONT_GOTHIC_24_BOLD,
  SYSFONT_GOTHIC_28,
  SYSFONT_GOTHIC_28_BOLD,
  SYSFONT_BITHAM_30_BLACK,
  SYSFONT_BITHAM_42_BOLD,
  SYSFONT_COUNT
} SysFont;

#define GLYPH_FIRST 0x20
#define GLYPH_LAST 0xFF
#define GLYPH_MISSING 255
#define GLYPH_WILDCARD_CP 0x25AF

// Ink metrics of a firmware glyph: top of the ink relative to the line top,
// ink height (0 for blank glyphs) and advance
typedef struct {
  int8_t top;
  uint8_t h;
  uint8_t adv;
} GlyphMetric;

extern const GlyphMetric g_glyph_metrics[SYSFONT_COUNT][GLYPH_LAST - GLYPH_FIRST + 1];
extern const GlyphMetric g_glyph_wildcard[SYSFONT_COUNT];

// Clock (fctx) fonts: avenir, bold, leco
#define CLOCK_FONT_COUNT 3
#define CLOCK_GLYPHS 11  // "0123456789:"

typedef struct {
  int16_t adv16;            // advance, 1/16 font units
  int16_t x0, x1, top, bottom;  // ink box, 1/4 font units, y up from the baseline
} ClockGlyph;

typedef struct {
  int16_t upem16;           // units per em, 1/16 font units
  ClockGlyph glyphs[CLOCK_GLYPHS];
} ClockFontInfo;

extern const ClockFontInfo g_clock_fonts[CLOCK_FONT_COUNT];
